  function v12Esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(m){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m])})}
  function v12Status(s){return tag(s,s==='已完成'||s==='医生已确认'||s==='已归档'||s==='已出结果'?'good':s==='危急值'||s==='危急值待处理'||s==='异常报告'?'bad':s==='待预约'||s==='待准备'||s==='待查看'||s==='待护士查看'||s==='待医生确认'||s==='待护士确认'?'warn':'info')}
  function v12Now(){return '2026-10-11 '+new Date().toTimeString().slice(0,5)}
