  function v12DisplayState(){if(V12_STATE.display==='empty')return '<div class="v11-info">当前筛选范围内暂无记录。可清除筛选或回到全部任务。</div>';if(V12_STATE.display==='error')return '<div class="v11-alert">数据同步失败，最后一次有效数据时间：2026-10-11 10:18。<button class="btn sm" onclick="v12SetDisplay(\'normal\')">重试</button></div>';if(V12_STATE.display==='permission')return '<div class="v11-info">当前角色无权访问该范围数据。</div>';return null}
  function v12SetDisplay(v){V12_STATE.display=v;render()}
  function v12Export(kind){V12_STORE.exports.push({kind:kind,time:v12Now(),operator:V12_ROLES[V12_STATE.role].user,status:'已生成'});V12Feedback('导出任务已生成，可在导出记录中下载 CSV 文件')}
  function v12Print(kind){V12_STATE.detail={type:'print',kind:kind};render()}
  function v12CloseDetail(){V12_STATE.detail=null;V12_STATE.feedback='';render()}
  function v12OpenPatient(id){V12_STATE.module=V12_STATE.role==='doctor'?'today':'patients';V12_STATE.sub=V12_STATE.role==='doctor'?'all':'detail';V12_STATE.detail={type:'patient',id:id};render()}
  function v12OpenExam(id){V12_STATE.detail={type:'exam',id:id};render()}
  function v12OpenReport(id){V12_STATE.detail={type:'report',id:id};render()}
  function v12OpenCritical(id){V12_STATE.detail={type:'critical',id:id};render()}
  function v12SetModule(id){V12_STATE.module=id;V12_STATE.sub=(V12_MODULES[V12_STATE.role]&&V12_MODULES[V12_STATE.role][id]||[['overview','总览']])[0][0];V12_STATE.query='';V12_STATE.filter='all';V12_STATE.page=1;V12_STATE.detail=null;V12_STATE.feedback='';render()}
  function v12SetSub(id){V12_STATE.sub=id;V12_STATE.page=1;V12_STATE.detail=null;V12_STATE.feedback='';render()}
  function v12Pager(total){var pages=Math.max(1,Math.ceil(total/6));return '<div class="pagination"><span>共 '+total+' 条数据</span><div class="pages">'+Array.from({length:Math.min(pages,4)},function(_,i){return '<button class="btn sm '+(V12_STATE.page===i+1?'primary':'')+'" onclick="v12SetPage('+(i+1)+')">'+(i+1)+'</button>'}).join('')+'</div></div>'}
  function v12SetPage(n){V12_STATE.page=n;render()}
  function v12RoleChange(role){V12_STATE.role=role;V12_STATE.module=(V12_ROLES[role].nav[0]||['dashboard'])[0];V12_STATE.sub=(V12_MODULES[role]&&V12_MODULES[role][V12_STATE.module]||[['overview','总览']])[0][0];V12_STATE.patientPage='home';V12_STATE.patientDoctor=null;V12_STATE.patientSlot=null;render()}
  function v12RoleShell(){var cfg=V12_ROLES[V12_STATE.role],mods=cfg.nav;return '<div class="brand">医路协同<small>患者诊疗流程协同与服务平台</small></div><div class="rolebox"><label>当前工作端</label><select id="role">'+Object.entries(V12_ROLES).map(function(x){return '<option value="'+x[0]+'" '+(x[0]===V12_STATE.role?'selected':'')+'>'+x[1].label+'</option>'}).join('')+'</select></div><div class="v11-primary-head">岗位工作模块</div><div class="v11-side-primary">'+mods.map(function(m){return '<button class="'+(V12_STATE.module===m[0]?'on':'')+'" onclick="v12SetModule(\''+m[0]+'\')"><span>▦</span>'+m[1]+'</button>'}).join('')+'</div><div class="foot">当前用户：'+cfg.user+'<br>数据范围：'+cfg.scope+'<br>数据同步：正常</div>'}
  function v12SubNav(){var cfg=V12_MODULES[V12_STATE.role]||{},subs=cfg[V12_STATE.module]||[['overview','工作区']];return '<aside class="v11-subnav"><h3>'+((V12_ROLES[V12_STATE.role].nav.find(function(x){return x[0]===V12_STATE.module})||['','工作区'])[1])+'</h3>'+subs.map(function(s){return '<button class="v11-subbtn '+(V12_STATE.sub===s[0]?'on':'')+'" onclick="v12SetSub(\''+s[0]+'\')">'+s[1]+'</button>'}).join('')+'</aside>'}
  function v12Header(){var cfg=V12_ROLES[V12_STATE.role];return '<div class="v11-scope"><span>当前用户：<b>'+cfg.user+'</b>　|　数据范围：<b>'+cfg.scope+'</b></span><span>最后同步：今日 10:28</span></div>'+(V12_STATE.feedback?'<div class="v11-info" style="margin-bottom:14px">'+v12Esc(V12_STATE.feedback)+'</div>':'')}
  function v12Title(h,sub,actions){return '<div class="title"><div><h1>'+h+'</h1><p>'+sub+'</p></div><div class="actions">'+(actions||'')+'</div></div>'}
  function v12TableRows(rows,columns,actions){if(!rows.length)return '<div class="v11-info">当前筛选范围内暂无记录。</div>';return '<div class="tablewrap"><table class="table v11-table"><thead><tr>'+columns.map(function(c){return '<th>'+c[0]+'</th>'}).join('')+'<th>操作</th></tr></thead><tbody>'+rows.map(function(r){return '<tr>'+columns.map(function(c){return '<td>'+(typeof c[1]==='function'?c[1](r):v12Esc(r[c[1]]||'—'))+'</td>'}).join('')+'<td>'+(actions?actions(r):'')+'</td></tr>'}).join('')+'</tbody></table></div>'}
  function v12PatientTable(rows){return v12TableRows(rows,[['📌住院号','id'],['姓名/床位',function(p){return '<b>'+p.name+'</b><br><span class="sub">'+p.gender+' · '+p.age+'岁 · '+p.bed+'</span>'}],['疾病类型/责任医生',function(p){return p.disease+'<br><span class="sub">'+p.doctor+'医生</span>'}],['当前任务',function(p){return p.next+'<br>'+v12Status(p.stage)}],['检查/报告',function(p){return p.exam+'<br>'+v12Status(p.report)}],['异常提醒',function(p){return p.alert==='无'?'<span class="sub">无</span>':'<span class="tag bad">'+p.alert+'</span>'}]],function(p){return btn('查看详情',"v12OpenPatient('"+p.id+"')",'btn primary')})}
  function v12DashboardNurse(){var pending=V12_STORE.exams.filter(function(x){return x.status==='待预约'||x.status==='待准备'}).length,report=V12_STORE.reports.filter(function(x){return x.status==='待护士查看'}).length,critical=V12_STORE.criticals.filter(function(x){return x.status!=='处置完成'}).length;return v12Title('病区工作台','8A 呼吸内科 · 今日任务按临床优先级排序',btn('查看消息中心',"v12SetModule('messages')",'btn primary'))+'<div class="v11-grid3"><button class="v11-stat" onclick="v12SetModule(\'patients\')"><small>在院患者</small><strong>'+V12_STORE.patients.length+'</strong><em>进入患者列表</em></button><button class="v11-stat" onclick="v12SetModule(\'coordination\')"><small>今日待检查</small><strong>24</strong><em>含 '+pending+' 条待协调</em></button><button class="v11-stat" onclick="v12SetSub(\'report\');v12SetModule(\'messages\')"><small>报告待查看</small><strong>'+report+'</strong><em>查看报告正文</em></button><button class="v11-stat" onclick="v12SetSub(\'critical\');v12SetModule(\'messages\')"><small>危急值处理</small><strong style="color:var(--bad)">'+critical+'</strong><em style="color:var(--bad)">需记录响应时间</em></button><button class="v11-stat" onclick="v12SetModule(\'followup\')"><small>待复查安排</small><strong>'+V12_STORE.followups.filter(function(x){return x.status==='待安排'}).length+'</strong><em>同步患者端</em></button><button class="v11-stat" onclick="v12SetModule(\'analytics\')"><small>人工复核</small><strong>4</strong><em>进入复核列表</em></button></div><div class="v11-two"><div class="v11-card"><div class="head"><h2>在院患者</h2>'+btn('查看全部',"v12SetModule('patients')")+'</div>'+v12PatientTable(V12_STORE.patients.slice(0,6))+'</div><div><div class="v11-card"><h2>今日关键提醒</h2><div class="v11-alert">赵敏 · 血氧饱和度 88% · 危急值待护士确认</div><div class="v11-info">检查前 15 分钟提醒：孙磊胸部 CT 预约 10:30，需确认携带腕带。</div><div class="actions" style="margin-top:12px">'+btn('进入危急值',"v12OpenCritical('CV-260801')",'btn bad')+btn('查看检查准备',"v12SetSub('prep');v12SetModule('coordination')")+'</div></div><div class="v11-card"><h2>临床闭环</h2><div class="v11-info">检查申请 → 预约 → 准备送出 → 执行 → 报告回传 → 医生确认 → 复查安排</div></div></div></div>'}
  function v12PatientsPage(){var q=V12_STATE.query.toLowerCase(),rows=V12_STORE.patients.filter(function(p){return !q||p.name.includes(q)||p.id.toLowerCase().includes(q)||p.bed.toLowerCase().includes(q)});var d=v12DisplayState();return v12Title('患者列表','8A 呼吸内科病区 · 搜索姓名、住院号或床号',btn('导出患者任务',"v12Export('患者任务')",'btn primary')+btn('打印摘要',"v12Print('患者任务')"))+'<div class="v11-card"><div class="filters"><input value="'+v12Esc(V12_STATE.query)+'" placeholder="姓名 / 住院号 / 床号" oninput="V12_STATE.query=this.value;V12_STATE.page=1;render()"><select onchange="V12_STATE.filter=this.value;render()"><option value="all">全部状态</option><option value="pending">待处理</option><option value="processing">处理中</option><option value="done">已处理</option></select>'+btn('清除筛选',"V12_STATE.query='';V12_STATE.filter='all';render()")+'</div>'+v12StateBar()+(d||v12PatientTable(rows))+v12Pager(rows.length)+'</div>'}
  function v12PatientDetail(){var id=V12_STATE.detail&&V12_STATE.detail.id||V12_STORE.patients[0].id,p=v12FindPatient(id);return v12Title('患者详情',p.id+' · '+p.name+' · '+p.bed,btn('返回患者列表',"v12CloseDetail()"))+ (p.alert!=='无'?'<div class="v11-alert"><b>异常提醒：</b>'+p.alert+' · 责任医生：'+p.doctor+' · 请按当前岗位权限处理</div>':'')+'<div class="v11-detail-top"><div><div class="v11-detail-name">'+p.name+' <span class="tag info">'+p.gender+' · '+p.age+'岁</span></div><div class="v11-detail-meta">住院号 '+p.id+'　床位 '+p.bed+'　疾病类型 '+p.disease+'　责任医生 '+p.doctor+'</div></div><div class="actions">'+btn('新增节点',"v12OpenAddNode('"+p.id+"')",'btn primary')+btn('通知医生',"v12NotifyDoctor('"+p.id+"')")+btn('预约复查',"v12BookFollowup('"+p.id+"')")+'</div></div><div class="v11-card"><h2>基础信息</h2><div class="v11-kv"><div><label>住院号</label><strong>'+p.id+'</strong></div><div><label>床位</label><strong>'+p.bed+'</strong></div><div><label>疾病类型</label><strong>'+p.disease+'</strong></div><div><label>责任医生</label><strong>'+p.doctor+'</strong></div><div><label>当前诊疗阶段</label><strong>'+p.stage+'</strong></div><div><label>当前任务</label><strong>'+p.next+'</strong></div><div><label>检查状态</label><strong>'+p.exam+'</strong></div><div><label>报告状态</label><strong>'+p.report+'</strong></div></div></div><div class="v11-two"><div class="v11-card"><h2>诊疗流程时间轴</h2><div class="timeline"><div class="step done">入院/接诊</div><div class="step done">检查预约</div><div class="step '+(p.stage==='待检查'?'cur':'done')+'">检查执行</div><div class="step '+(p.report==='待出报告'?'cur':'done')+'">报告回传</div><div class="step '+(p.stage==='危急值待确认'?'cur':'')+'">医生确认</div><div class="step '+(p.stage==='复查待安排'?'cur':'')+'">复查协同</div></div><div class="v11-info">下一步：'+p.next+'；最后更新时间：'+p.updated+'</div></div><div class="v11-card"><h2>关联记录</h2><div class="actions">'+btn('检查与护理记录',"v12SetSub('records')",'btn primary')+btn('报告与危急值',"v12SetSub('reports')")+btn('打印摘要',"v12Print('患者详情')")+'</div></div></div>'}
  function v12OpenAddNode(id){V12_STATE.detail={type:'add-node',id:id};render()}
  function v12NotifyDoctor(id){var p=v12FindPatient(id);V12_STORE.messages.unshift({id:'MSG-'+Date.now(),type:'critical',patient:p.name,patientId:p.id,text:'护士已通知医生关注：'+p.alert,deadline:'立即',status:'未读'});v12Audit('通知医生','患者',id,'已发送危急值关注通知');v12Feedback('已通知 '+p.doctor+' 医生，并记录通知时间 '+v12Now())}
  function v12AddExam(id){var p=v12FindPatient(id);var ex={id:'EX-'+Date.now(),patientId:id,patient:p.name,dept:'8A 呼吸内科',project:document.getElementById('v12NodeProject').value||'肺功能复查',location:document.getElementById('v12NodeLocation').value||'肺功能室',appointment:document.getElementById('v12NodeTime').value||'待协调',prep:document.getElementById('v12NodePrep').value||'待确认',status:'待预约',expected:'待计算',operator:V12_ROLES[V12_STATE.role].user,changedAt:v12Now()};V12_STORE.exams.unshift(ex);p.stage='待检查';p.exam=ex.project;p.next='完成检查预约';V12_STORE.messages.unshift({id:'MSG-'+Date.now(),type:'prep',patient:p.name,patientId:id,text:'新增检查节点：'+ex.project,deadline:'待预约',status:'未读'});v12Audit('新增检查节点','检查',ex.id,'新增'+ex.project);V12_STATE.detail={type:'patient',id:id};v12Feedback('检查节点已创建，已同步患者时间轴、检查队列和工作台计数')}
  function v12AddNodeView(id){return v12Title('新增检查节点','步骤 2/3 · 填写检查项目、时间、地点和准备要求',btn('取消',"v12CloseDetail()"))+'<div class="v11-card"><div class="v11-form"><label>检查项目 *</label><input id="v12NodeProject" value="肺功能复查"><label>检查日期/时间 *</label><input id="v12NodeTime" value="2026-10-13 09:30"><label>检查地点 *</label><input id="v12NodeLocation" value="肺功能室"><label>准备要求</label><textarea id="v12NodePrep" rows="3">检查前避免剧烈活动，携带腕带</textarea><div class="modalactions">'+btn('返回患者详情',"v12CloseDetail()")+btn('保存并生成检查任务',"v12AddExam('"+id+"')",'btn primary')+'</div></div></div>'}
  function v12ExamList(mode){var rows=V12_STORE.exams.filter(function(x){if(mode==='queue')return x.status==='待预约'||x.status==='待准备';if(mode==='prep')return x.status==='待准备'||x.prep==='待确认';if(mode==='tracking')return true;if(mode==='reports')return x.status==='待出报告'||x.status==='已完成';return true});var d=v12DisplayState();var columns=[['📌检查订单','id'],['患者/住院号',function(x){return '<b>'+x.patient+'</b><br><span class="sub">'+x.patientId+'</span>'}],['检查项目/地点',function(x){return x.project+'<br><span class="sub">'+x.location+'</span>'}],['预约/预计报告',function(x){return x.appointment+'<br>'+x.expected}],['准备要求','prep'],['状态',function(x){return v12Status(x.status)}],['操作者/变更时间',function(x){return x.operator+'<br><span class="sub">'+x.changedAt+'</span>'}]];var actions=function(x){if(mode==='prep')return btn('完成准备并送出',"v12PrepareExam('"+x.id+"')",'btn primary');if(x.status==='待预约')return btn('完成预约',"v12BookExam('"+x.id+"')",'btn primary');return btn('查看检查详情',"v12OpenExam('"+x.id+"')",'btn primary')};return v12Title(mode==='queue'?'检查队列':mode==='prep'?'检查准备与送出':mode==='tracking'?'检查状态追踪':'检查与报告','检查申请、准备、执行、报告回传由同一检查订单驱动',btn('导出检查清单',"v12Export('检查清单')",'btn primary'))+'<div class="v11-card">'+v12StateBar()+(d||v12TableRows(rows,columns,actions))+v12Pager(rows.length)+'</div>'}
  function v12BookExam(id){var x=v12FindExam(id);x.status='已预约';x.appointment='今日 10:30';x.prep='待确认禁食/携带腕带';x.changedAt=v12Now();v12Audit('预约检查','检查',id,'已确认检查时间和地点');v12Feedback('检查已预约，准备任务已进入检查准备队列')}
  function v12PrepareExam(id){var x=v12FindExam(id);x.status='检查中';x.prep='准备完成并已送出患者';x.changedAt=v12Now();var p=v12FindPatient(x.patientId);p.stage='检查中';p.next='等待检查完成和报告回传';v12Audit('完成检查准备','检查',id,'已确认身份、准备要求并送出患者');v12Feedback('检查准备已完成并送出患者，状态已进入检查中')}
  function v12ExamDetail(id){var x=v12FindExam(id),p=v12FindPatient(x.patientId);return v12Title('检查订单详情',x.id+' · '+x.patient+' · '+x.project,btn('返回检查队列',"v12CloseDetail()"))+'<div class="v11-two"><div class="v11-card"><h2>检查信息</h2><div class="v11-kv"><div><label>患者/住院号</label><strong>'+p.name+' · '+p.id+'</strong></div><div><label>检查项目</label><strong>'+x.project+'</strong></div><div><label>地点</label><strong>'+x.location+'</strong></div><div><label>预约时间</label><strong>'+x.appointment+'</strong></div><div><label>准备要求</label><strong>'+x.prep+'</strong></div><div><label>预计报告</label><strong>'+x.expected+'</strong></div></div></div><div class="v11-card"><h2>状态迁移</h2><div class="timeline"><div class="step done">待预约</div><div class="step '+(x.status==='待预约'?'cur':'done')+'">已预约</div><div class="step '+(x.status==='待准备'?'cur':'done')+'">准备完成</div><div class="step '+(x.status==='检查中'?'cur':'')+'">检查中</div><div class="step '+(x.status==='已完成'?'cur':'')+'">检查完成</div><div class="step">报告回传</div></div><div class="actions">'+(x.status==='待预约'?btn('完成预约',"v12BookExam('"+x.id+"')",'btn primary'):'')+(x.status==='已预约'||x.status==='待准备'?btn('完成准备并送出',"v12PrepareExam('"+x.id+"')",'btn primary'):'')+(x.status==='检查中'?btn('医技标记已完成',"v12CompleteExam('"+x.id+"')",'btn primary'):'')+'</div></div></div>'}
  function v12CompleteExam(id){var x=v12FindExam(id),p=v12FindPatient(x.patientId);x.status='已完成';x.expected='今日 12:00';x.changedAt=v12Now();p.stage='报告待查看';p.report='待护士查看';V12_STORE.messages.unshift({id:'MSG-'+Date.now(),type:'report',patient:p.name,patientId:p.id,text:x.project+'检查已完成，报告待查看',deadline:'今日 12:00',status:'未读'});v12Audit('完成检查','检查',id,'医技已确认样本/影像质量合格');v12Feedback('检查已完成，护士和医生报告待办已同步')}
  function v12ReportList(mode){var rows=V12_STORE.reports.filter(function(r){if(mode==='critical')return r.status==='危急值';if(mode==='abnormal')return r.result!=='检查结果已生成，需结合临床判断';if(mode==='confirmed')return r.status==='医生已确认';return r.status==='待护士查看'||r.status==='危急值'||r.status==='待出结果'});var columns=[['📌报告编号','id'],['患者/住院号',function(r){return '<b>'+r.patient+'</b><br><span class="sub">'+r.patientId+'</span>'}],['检查项目','project'],['结果',function(r){return r.result}],['参考区间','reference'],['出报告时间','issuedAt'],['状态',function(r){return v12Status(r.status)}]];return v12Title(mode==='critical'?'危急值提醒':mode==='abnormal'?'异常报告':mode==='confirmed'?'医生确认记录':'待查看报告','报告正文、异常值、参考区间和查看链路均可追踪',btn('导出报告清单',"v12Export('报告清单')",'btn primary'))+'<div class="v11-card">'+v12StateBar()+v12TableRows(rows,columns,function(r){return r.status==='危急值'?btn('处理危急值',"v12OpenCritical('CV-260801')",'btn bad'):btn('查看报告',"v12OpenReport('"+r.id+"')",'btn primary')})+v12Pager(rows.length)+'</div>'}
  function v12ReportDetail(id){var r=v12FindReport(id),p=v12FindPatient(r.patientId);return v12Title('报告详情',r.id+' · '+p.name+' · '+r.project,btn('返回报告待办',"v12CloseDetail()"))+(r.status==='危急值'?'<div class="v11-alert"><b>危急值：</b>'+r.result+' · 需要完成护士确认和医生确认</div>':'')+'<div class="v11-two"><div class="v11-card"><h2>报告正文</h2><div class="v11-kv"><div><label>患者/住院号</label><strong>'+p.name+' · '+p.id+'</strong></div><div><label>检查项目</label><strong>'+r.project+'</strong></div><div><label>结果</label><strong>'+r.result+'</strong></div><div><label>参考区间</label><strong>'+r.reference+'</strong></div><div><label>报告医生</label><strong>'+r.doctor+'</strong></div><div><label>出报告时间</label><strong>'+r.issuedAt+'</strong></div><div><label>护士查看时间</label><strong>'+ (r.nurseViewedAt||'—')+'</strong></div><div><label>医生查看时间</label><strong>'+ (r.doctorViewedAt||'—')+'</strong></div></div></div><div class="v11-card"><h2>处理动作</h2><div class="v11-info">报告状态：'+r.status+'。处理后会同步护士、医生和患者端进度。</div><div class="actions" style="margin-top:12px">'+(r.status==='待护士查看'||r.status==='危急值'?btn('标记护士已查看',"v12ViewReport('"+r.id+"')",'btn primary'):'')+(r.status==='待护士查看'||r.status==='危急值'?btn('通知医生',"v12NotifyDoctor('"+p.id+"')"):'')+btn('打印报告',"v12Print('报告详情')")+'</div></div></div>'}
  function v12ViewReport(id){var r=v12FindReport(id);r.nurseViewedAt=v12Now();if(r.status==='待护士查看')r.status='待医生确认';var p=v12FindPatient(r.patientId);p.report='待医生确认';v12Audit('查看报告','报告',id,'护士已查看报告正文');v12Feedback('报告已标记护士查看，医生端已新增待确认任务')}
  function v12CriticalDetail(id){var c=V12_STORE.criticals.find(function(x){return x.id===id})||V12_STORE.criticals[0],p=v12FindPatient(c.patientId);return v12Title('危急值处置详情',c.id+' · '+p.name+' · '+c.project,btn('返回危急值列表',"v12CloseDetail()"))+'<div class="v11-alert"><b>'+c.value+'</b> · 发现 '+c.foundAt+' · 参考范围 '+c.reference+' · 当前 '+c.status+'</div><div class="v11-two"><div class="v11-card"><h2>事件摘要</h2><div class="v11-kv"><div><label>患者/住院号</label><strong>'+p.name+' · '+p.id+'</strong></div><div><label>异常项目</label><strong>'+c.project+'</strong></div><div><label>异常值</label><strong>'+c.value+'</strong></div><div><label>参考范围</label><strong>'+c.reference+'</strong></div></div><div class="v11-info" style="margin-top:13px">护士响应：'+(c.nurseAt||'待确认')+'；医生通知：'+(c.doctorAt||'待通知')+'；处置完成：'+(c.doneAt||'待完成')+'</div></div><div class="v11-card"><h2>处置记录</h2><div class="v11-form"><label>工号 *</label><input id="v12CriticalStaff" value="'+(V12_ROLES[V12_STATE.role].user==='李护士'?'NUR-008':'DOC-021')+'"><label>处置意见 *</label><textarea id="v12CriticalNote" rows="4" placeholder="填写异常复核、联系对象和处置措施">'+(c.note||'')+'</textarea><div class="actions">'+btn('确认已阅读并通知医生',"v12ConfirmCritical('"+c.id+"','nurse')",'btn primary')+btn('医生确认并完成处置',"v12ConfirmCritical('"+c.id+"','doctor')",'btn bad')+'</div></div></div></div>'}
  function v12ConfirmCritical(id,actor){var c=V12_STORE.criticals.find(function(x){return x.id===id});if(!c)return;if(actor==='nurse'){c.nurseAt=v12Now();c.status='待医生确认';V12_STORE.messages.unshift({id:'MSG-'+Date.now(),type:'critical',patient:c.patient,patientId:c.patientId,text:'护士已确认危急值并通知医生',deadline:'立即',status:'未读'});v12Audit('通知医生','危急值',id,'护士确认已阅读并通知医生')}else{c.doctorAt=v12Now();c.doneAt=v12Now();c.status='处置完成';c.note=(document.getElementById('v12CriticalNote')||{}).value||'已完成临床处置';var p=v12FindPatient(c.patientId);p.stage='已完成';p.alert=c.value+' · 已处置';v12Audit('完成处置','危急值',id,c.note)}v12Feedback(actor==='nurse'?'已记录护士响应时间，医生端出现待确认事件':'医生处置已完成，护士端危急值历史已更新')}
